-- ---------- CREATE TABLE ----------
-- Table: CMP_CATEGORIA
CREATE TABLE "CMP_CATEGORIA" (
    "CAT_ID_CATEGORIA" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER NOCYCLE NOKEEP NOSCALE NOT NULL ENABLE,
    "CAT_NOMBRE_CATEGORIA" VARCHAR2(100) NOT NULL ENABLE,
    "CAT_ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE,
    CONSTRAINT "CK_CMP_CAT_ACTIVO" CHECK (CAT_ACTIVO IN (0, 1)) ENABLE,
    CONSTRAINT "PK_CMP_CATEGORIA" PRIMARY KEY ("CAT_ID_CATEGORIA") USING INDEX TABLESPACE "USERS" ENABLE
) TABLESPACE "USERS";

