    CONSTRAINT "PK_CMP_LOTE" PRIMARY KEY ("LOT_ID_LOTE") USING INDEX TABLESPACE "USERS" ENABLE,
    CONSTRAINT "UQ_CMP_LOTE_NUM_ART" UNIQUE ("LOT_NUMERO_LOTE", "LOT_CODIGO_ARTICULO") USING INDEX TABLESPACE "USERS" ENABLE
) TABLESPACE "USERS";

-- Table: CMP_INVENTARIO
CREATE TABLE "CMP_INVENTARIO" (
    "INV_ID_INVENTARIO" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER NOCYCLE NOKEEP NOSCALE NOT NULL ENABLE,
    "INV_ID_BODEGA" NUMBER NOT NULL ENABLE,
    "INV_CODIGO_ARTICULO" VARCHAR2(20) NOT NULL ENABLE,
    "INV_ID_UBICACION_DEFECTO" NUMBER,
    "INV_EXISTENCIA_ACTUAL" NUMBER(18,4) DEFAULT 0 NOT NULL ENABLE,
    "INV_STOCK_RESERVADO" NUMBER(18,4) DEFAULT 0 NOT NULL ENABLE,
    "INV_STOCK_DISPONIBLE" NUMBER(18,4) DEFAULT 0 NOT NULL ENABLE,
    "INV_STOCK_MINIMO" NUMBER(18,4) DEFAULT 0 NOT NULL ENABLE,
    "INV_STOCK_MAXIMO" NUMBER(18,4) DEFAULT 0 NOT NULL ENABLE,
    "INV_PUNTO_REORDEN" NUMBER(18,4) DEFAULT 0 NOT NULL ENABLE,
    "INV_COSTO_PROMEDIO_LOCAL" NUMBER(18,4) DEFAULT 0 NOT NULL ENABLE,
    "INV_ULTIMO_COSTO_COMPRA" NUMBER(18,4) DEFAULT 0 NOT NULL ENABLE,
    "INV_FECHA_ULTIMO_MOVIMIENTO" TIMESTAMP (6),
    CONSTRAINT "CK_CMP_INV_EXISTENCIAS" CHECK (INV_STOCK_RESERVADO >= 0 AND INV_STOCK_MINIMO >= 0 AND INV_STOCK_MAXIMO >= INV_STOCK_MINIMO) ENABLE,
    CONSTRAINT "PK_CMP_INVENTARIO" PRIMARY KEY ("INV_ID_INVENTARIO") USING INDEX TABLESPACE "USERS" ENABLE,
    CONSTRAINT "UQ_CMP_INV_BOD_ART" UNIQUE ("INV_ID_BODEGA", "INV_CODIGO_ARTICULO") USING INDEX TABLESPACE "USERS" ENABLE
) TABLESPACE "USERS";

-- Table: CMP_TIPO_MOVIMIENTO_INV
CREATE TABLE "CMP_TIPO_MOVIMIENTO_INV" (
    "TMI_ID_TIPO_MOVIMIENTO" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER NOCYCLE NOKEEP NOSCALE NOT NULL ENABLE,
