    CONSTRAINT "CK_CMP_TMI_AFECTA" CHECK (TMI_AFECTA_COSTO IN (0, 1)) ENABLE,
    CONSTRAINT "CK_CMP_TMI_ACTIVO" CHECK (TMI_ACTIVO IN (0, 1)) ENABLE,
    CONSTRAINT "PK_CMP_TIPO_MOV_INV" PRIMARY KEY ("TMI_ID_TIPO_MOVIMIENTO") USING INDEX TABLESPACE "USERS" ENABLE,
    CONSTRAINT "UQ_CMP_TMI_CODIGO" UNIQUE ("TMI_CODIGO") USING INDEX TABLESPACE "USERS" ENABLE
) TABLESPACE "USERS";

